`TSpinBox` lives in `FMX.SpinBox`, a unit of its own - not `FMX.StdCtrls`, not `FMX.Edit`. The type of `Align` is `TAlignLayout`, declared in `FMX.Types` together with `TFmxObject`. Both units go in the interface `uses` clause, since the signature names their types. The parent owns the box, so the box is freed with it; `Min` and `Max` are set before `Value`, which a spin box keeps inside its range.

```delphi
unit QuantityField;

interface

uses
  FMX.Types,
  FMX.SpinBox;

// A spin box for a quantity from 1 to 99, starting at 1, aligned to the top of its parent
function AddQuantityField(const AParent: TFmxObject): TSpinBox;

implementation

function AddQuantityField(const AParent: TFmxObject): TSpinBox;
begin
  // TSpinBox lives in FMX.SpinBox; TAlignLayout and TFmxObject in FMX.Types
  Result := TSpinBox.Create(AParent);
  Result.Parent := AParent;
  Result.Align := TAlignLayout.Top;
  Result.Min := 1;
  Result.Max := 99;
  Result.Value := 1;
end;

end.
```

This Delphi FireMonkey (FMX) unit does not compile:

```
TermsBox.pas(6): error F2613: Unit 'FMX.CheckBox' not found.
```

```delphi
unit TermsBox;

interface

uses
  FMX.CheckBox;

// The "I accept the terms" box of a sign-up form: its caption, and not ticked
procedure SetupTermsBox(const ABox: TCheckBox);

implementation

procedure SetupTermsBox(const ABox: TCheckBox);
begin
  ABox.Caption := 'I accept the terms';
  ABox.Checked := False;
end;

end.
```

There is no `FMX.CheckBox`: FireMonkey's `TCheckBox` is declared in `FMX.StdCtrls`, together with the button, the label and the switch. F2613 is fatal, so the compiler stopped there and never reached the two lines that fail next: a FireMonkey check box shows its caption in `Text` and is ticked through `IsChecked`; `Caption` and `Checked` are not its names. Fix all three before compiling again.

```delphi
unit TermsBox;

interface

uses
  FMX.StdCtrls;

// The "I accept the terms" box of a sign-up form: its caption, and not ticked
procedure SetupTermsBox(const ABox: TCheckBox);

implementation

procedure SetupTermsBox(const ABox: TCheckBox);
begin
  // a FireMonkey check box shows Text and is ticked through IsChecked
  ABox.Text := 'I accept the terms';
  ABox.IsChecked := False;
end;

end.
```

This Delphi FireMonkey (FMX) unit does not compile:

```
PanelFill.pas(15): error E2003: Undeclared identifier: 'alClient'
```

```delphi
unit PanelFill;

interface

uses
  FMX.StdCtrls;

// The content panel takes all the room its parent has left
procedure FillParent(const APanel: TPanel);

implementation

procedure FillParent(const APanel: TPanel);
begin
  APanel.Align := alClient;
end;

end.
```

`alClient` is not a FireMonkey name. FireMonkey aligns a control with the scoped type `TAlignLayout`, so the value is `TAlignLayout.Client`. Changing the name is not enough: `TAlignLayout` is declared in `FMX.Types`, and with only `FMX.StdCtrls` in the `uses` clause the compiler stops at `TAlignLayout` instead. `FMX.Types` goes in the implementation `uses` clause, since only the body needs it.

```delphi
unit PanelFill;

interface

uses
  FMX.StdCtrls;

// The content panel takes all the room its parent has left
procedure FillParent(const APanel: TPanel);

implementation

uses
  FMX.Types;

procedure FillParent(const APanel: TPanel);
begin
  // alClient is not a FireMonkey name: FireMonkey aligns with TAlignLayout, declared in FMX.Types
  APanel.Align := TAlignLayout.Client;
end;

end.
```

The square is a `TRectangle`, from `FMX.Objects`. A new rectangle has a solid fill and a solid border, so the border has to be switched off with `Stroke.Kind := TBrushKind.None`. `TBrushKind` is declared in `FMX.Graphics` and `TAlphaColor` in `System.UITypes`. The interface `uses` clause needs `System.UITypes`, `FMX.Types` and `FMX.Objects`, because the signature names their types; the implementation adds `FMX.Graphics`.

```delphi
unit ColorSwatch;

interface

uses
  System.UITypes,
  FMX.Types,
  FMX.Objects;

// A 24 x 24 square filled with AColor, with no border, added to AParent
function AddSwatch(const AParent: TFmxObject; const AColor: TAlphaColor): TRectangle;

implementation

uses
  FMX.Graphics;

function AddSwatch(const AParent: TFmxObject; const AColor: TAlphaColor): TRectangle;
begin
  // TRectangle lives in FMX.Objects; the kinds of a brush (TBrushKind) in FMX.Graphics
  Result := TRectangle.Create(AParent);
  Result.Parent := AParent;
  Result.Width := 24;
  Result.Height := 24;
  Result.Fill.Kind := TBrushKind.Solid;
  Result.Fill.Color := AColor;
  Result.Stroke.Kind := TBrushKind.None;
end;

end.
```

In this Delphi FireMonkey (FMX) unit, a click on the corner of the button where the badge sits does nothing: the button never gets it. Fix it.

```delphi
unit AvatarBadge;

interface

uses
  FMX.Objects,
  FMX.StdCtrls;

// Puts the badge image over the top-right corner of the button
procedure PlaceBadge(const AButton: TButton; const ABadge: TImage);

implementation

procedure PlaceBadge(const AButton: TButton; const ABadge: TImage);
begin
  ABadge.Parent := AButton.Parent;
  ABadge.SetBounds(AButton.Position.X + AButton.Width - 12, AButton.Position.Y - 4, 16, 16);
  ABadge.BringToFront;
end;

end.
```

The badge is a `TImage`, and an image takes clicks: its `HitTest` is `True` by default. It sits on top of the button's corner, so FireMonkey gives the click there to the badge, and the button never sees it. The badge is only a picture, so it lets the clicks through: `ABadge.HitTest := False`. It is drawn exactly as before; only the clicks change.

```delphi
unit AvatarBadge;

interface

uses
  FMX.Objects,
  FMX.StdCtrls;

// Puts the badge image over the top-right corner of the button
procedure PlaceBadge(const AButton: TButton; const ABadge: TImage);

implementation

procedure PlaceBadge(const AButton: TButton; const ABadge: TImage);
begin
  ABadge.Parent := AButton.Parent;
  ABadge.SetBounds(AButton.Position.X + AButton.Width - 12, AButton.Position.Y - 4, 16, 16);
  ABadge.BringToFront;
  // a TImage takes clicks (HitTest is True by default): the badge on top would keep the ones meant for the
  // button below it
  ABadge.HitTest := False;
end;

end.
```

This Delphi unit does not compile:

```
HitCounter.pas(19): error E2003: Undeclared identifier: 'TInterlocked'
HitCounter.pas(19): error E2066: Missing operator or semicolon
```

```delphi
unit HitCounter;

interface

type
  // Counts the hits of a page; Hit is called from several threads at once
  THitCounter = class
  private
    FHits: Integer;
  public
    procedure Hit;
    function Hits: Integer;
  end;

implementation

procedure THitCounter.Hit;
begin
  TInterlocked.Increment(FHits);
end;

function THitCounter.Hits: Integer;
begin
  Result := FHits;
end;

end.
```

`TInterlocked` is declared in `System.SyncObjs`, and the unit has no `uses` clause at all. The E2066 on the same line is the compiler losing its way after the unknown name; it goes away with the first error. Only the implementation uses the class, so `System.SyncObjs` goes in the implementation `uses` clause. `TInterlocked.Increment` is what keeps the count right when several threads call `Hit` at once.

```delphi
unit HitCounter;

interface

type
  // Counts the hits of a page; Hit is called from several threads at once
  THitCounter = class
  private
    FHits: Integer;
  public
    procedure Hit;
    function Hits: Integer;
  end;

implementation

uses
  System.SyncObjs;

procedure THitCounter.Hit;
begin
  TInterlocked.Increment(FHits);
end;

function THitCounter.Hits: Integer;
begin
  Result := FHits;
end;

end.
```

This Delphi unit does not compile:

```
NameOrder.pas(15): error E2003: Undeclared identifier: 'TComparer'
NameOrder.pas(15): error E2029: '(' expected but '>' found
NameOrder.pas(20): error E2003: Undeclared identifier: 'CompareStr'
NameOrder.pas(21): error E2089: Invalid typecast
```

```delphi
unit NameOrder;

interface

// Shortest names first; names of the same length in alphabetical order
procedure SortByLength(var ANames: TArray<string>);

implementation

uses
  System.Generics.Collections;

procedure SortByLength(var ANames: TArray<string>);
begin
  TArray.Sort<string>(ANames, TComparer<string>.Construct(
    function(const A, B: string): Integer
    begin
      Result := Length(A) - Length(B);
      if Result = 0 then
        Result := CompareStr(A, B);
    end));
end;

end.
```

Two units are missing. `TComparer<T>` is declared in `System.Generics.Defaults`: `System.Generics.Collections` has `TArray` and `TList<T>`, not the comparers. The E2029 on the same line is the compiler reading `TComparer<string>` as a comparison once the name is unknown. `CompareStr` is in `System.SysUtils`, and the E2089 after it is its echo. With the three units in the implementation `uses` clause the sort compiles: shortest names first, and names of the same length in alphabetical order.

```delphi
unit NameOrder;

interface

// Shortest names first; names of the same length in alphabetical order
procedure SortByLength(var ANames: TArray<string>);

implementation

uses
  System.SysUtils,
  System.Generics.Collections,
  System.Generics.Defaults;

procedure SortByLength(var ANames: TArray<string>);
begin
  TArray.Sort<string>(ANames, TComparer<string>.Construct(
    function(const A, B: string): Integer
    begin
      Result := Length(A) - Length(B);
      if Result = 0 then
        Result := CompareStr(A, B);
    end));
end;

end.
```

`FormatDateTime` does it once the milliseconds are a `TDateTime`, which is a fraction of a day: `AMilliseconds / MSecsPerDay`. The trap is the minutes. In a format, `nn` is always the minutes, while `mm` is the month unless it comes right after an hour: `mm:ss.zzz` gives `12:23.250` for 83250, the 12 being the month of day zero. So the format is `nn:ss.zzz`.

```delphi
unit LapTimes;

interface

// A lap time under one hour as minutes:seconds.milliseconds - 83250 gives '01:23.250'
function LapText(const AMilliseconds: Integer): string;

implementation

uses
  System.SysUtils;

function LapText(const AMilliseconds: Integer): string;
begin
  // nn is the minutes; mm here would be the MONTH (it means minutes only right after an hour)
  Result := FormatDateTime('nn:ss.zzz', AMilliseconds / MSecsPerDay);
end;

end.
```

Delphi strings start at 1, so the last four characters start at `Length(ANumber) - 3`, not at `Length(ANumber) - 4`: `Copy(ANumber, Length(ANumber) - 3, 4)`. With exactly four digits that is `Copy(ANumber, 1, 4)`, the whole number.

```delphi
unit CardMask;

interface

// '**** ' and the last four digits of a card number (digits only, at least four)
function MaskCard(const ANumber: string): string;

implementation

function MaskCard(const ANumber: string): string;
begin
  // a string starts at 1, so its last four characters start at Length - 3
  Result := '**** ' + Copy(ANumber, Length(ANumber) - 3, 4);
end;

end.
```

In Delphi a `case` statement cannot select on a string: it needs an ordinal value. `IndexText` (`System.StrUtils`) finds a string in a list without regard to case and gives its index, or -1 when nothing matches. The index plus one is then the ISO number, and 0 for anything else.

```delphi
unit WeekdayNames;

interface

// The ISO number of an English weekday name in any case: Monday 1 to Sunday 7; anything else 0
function WeekdayNumber(const AName: string): Integer;

implementation

uses
  System.StrUtils;

function WeekdayNumber(const AName: string): Integer;
begin
  // a case statement needs an ordinal value; IndexText compares without regard to case, and gives -1 when
  // nothing matches
  Result := IndexText(AName, ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']) + 1;
end;

end.
```

`Round` does not round halves up: it rounds a half to the even number, so `Round(2.5)` is 2 and `Round(3.5)` is 4. `SimpleRoundTo` (`System.Math`) rounds a half away from zero, which is "halves up" for a quantity that is never negative. With 0 digits it gives a whole number, and `Trunc` turns it into an `Integer`.

```delphi
unit PackCount;

interface

// A quantity (never negative) rounded to whole units, halves up: 2.5 gives 3
function WholeUnits(const AQuantity: Double): Integer;

implementation

uses
  System.Math;

function WholeUnits(const AQuantity: Double): Integer;
begin
  // Round would give 2 for 2.5: it rounds a half to the even number. SimpleRoundTo rounds a half up.
  Result := Trunc(SimpleRoundTo(AQuantity, 0));
end;

end.
```

The RTL already has it: `WeekOfTheYear` in `System.DateUtils` follows ISO 8601. Weeks start on Monday, and week 1 is the one that holds the year's first Thursday, so 3 January 2021 is in week 53 (of 2020) and 30 December 2024 in week 1 (of 2025). The time of day does not change the week.

```delphi
unit WeekNumbers;

interface

// The ISO 8601 week number of a date (weeks start on Monday; week 1 holds the year's first Thursday)
function IsoWeek(const ADate: TDateTime): Integer;

implementation

uses
  System.DateUtils;

function IsoWeek(const ADate: TDateTime): Integer;
begin
  // WeekOfTheYear follows ISO 8601: 3 January 2021 is in week 53 (of 2020), 30 December 2024 in week 1
  Result := WeekOfTheYear(ADate);
end;

end.
```

`IncMonth` (`System.SysUtils`) is exactly that. It adds whole months and stops at the last day of a shorter month (31 January 2024 plus one month is 29 February 2024); it takes negative months, and it keeps the time of day.

```delphi
unit DueDates;

interface

// The same day AMonths months later (earlier when negative), or the last day of that month when it is shorter;
// the time of day stays
function DueDate(const AStart: TDateTime; const AMonths: Integer): TDateTime;

implementation

uses
  System.SysUtils;

function DueDate(const AStart: TDateTime; const AMonths: Integer): TDateTime;
begin
  // IncMonth already stops at the last day of a shorter month, and keeps the time
  Result := IncMonth(AStart, AMonths);
end;

end.
```

`ChangeFileExt` (`System.SysUtils`) does it: it replaces what follows the last dot of the file name, and adds the extension when there is none. It looks for that dot only after the last folder separator, so the dot of `my.docs` is left alone. `TPath` has no `ChangeExtension` in Delphi - that is the .NET name, and the compiler answers it with E2003.

```delphi
unit PreviewFiles;

interface

// The file name with the extension .pdf instead of the one it had, or added when it had none
function PreviewName(const AFileName: string): string;

implementation

uses
  System.SysUtils;

function PreviewName(const AFileName: string): string;
begin
  // ChangeFileExt looks for the dot only after the last folder separator
  Result := ChangeFileExt(AFileName, '.pdf');
end;

end.
```

Add to this Delphi unit a function `SamePhone(const A, B: string): Boolean`: true when two phone numbers, as people type them, are the same number.

```delphi
unit PhoneBook;

interface

// The digits of a phone number, with '+' first for an international one ('00' at the start counts as '+'):
// '+34 600-12 34 56' and '0034 600 123 456' both give '+34600123456'
function NormalizePhone(const APhone: string): string;

implementation

uses
  System.SysUtils;

function NormalizePhone(const APhone: string): string;
var
  C: Char;
begin
  Result := '';
  for C in Trim(APhone) do
    if CharInSet(C, ['0'..'9']) or ((C = '+') and (Result = '')) then
      Result := Result + C;
  if Result.StartsWith('00') then
    Result := '+' + Copy(Result, 3, MaxInt);
end;

end.
```

The unit already knows what makes two phone numbers the same: `NormalizePhone` keeps the digits, keeps a leading `+`, and reads a leading `00` as `+`. `SamePhone` compares what it gives for each number. A second filter written inside `SamePhone` would forget one of those rules today, or the next one tomorrow.

```delphi
unit PhoneBook;

interface

// The digits of a phone number, with '+' first for an international one ('00' at the start counts as '+'):
// '+34 600-12 34 56' and '0034 600 123 456' both give '+34600123456'
function NormalizePhone(const APhone: string): string;
// True when two phone numbers, as people type them, are the same number
function SamePhone(const A, B: string): Boolean;

implementation

uses
  System.SysUtils;

function NormalizePhone(const APhone: string): string;
var
  C: Char;
begin
  Result := '';
  for C in Trim(APhone) do
    if CharInSet(C, ['0'..'9']) or ((C = '+') and (Result = '')) then
      Result := Result + C;
  if Result.StartsWith('00') then
    Result := '+' + Copy(Result, 3, MaxInt);
end;

function SamePhone(const A, B: string): Boolean;
begin
  Result := NormalizePhone(A) = NormalizePhone(B);
end;

end.
```

A customer with exactly 50.00 in the cart saw "Free shipping!" and paid no shipping at checkout, but the invoice shows a shipping line of 4.95. Fix this Delphi unit.

```delphi
unit CartTotals;

interface

// What the cart page shows under the subtotal
function CartBanner(const ASubtotal: Currency): string;
// The shipping line of the invoice
function ShippingCost(const ASubtotal: Currency): Currency;
// What the checkout charges
function CheckoutTotal(const ASubtotal: Currency): Currency;

implementation

uses
  System.SysUtils;

function CartBanner(const ASubtotal: Currency): string;
begin
  if ASubtotal >= 50 then
    Result := 'Free shipping!'
  else
    Result := Format('Add %.2f more for free shipping', [50 - ASubtotal], TFormatSettings.Invariant);
end;

function ShippingCost(const ASubtotal: Currency): Currency;
begin
  if ASubtotal > 50 then
    Result := 0
  else
    Result := 4.95;
end;

function CheckoutTotal(const ASubtotal: Currency): Currency;
begin
  if ASubtotal >= 50 then
    Result := ASubtotal
  else
    Result := ASubtotal + 4.95;
end;

end.
```

The free-shipping rule is written three times, and the copy in `ShippingCost` drifted: it says "more than 50" where the other two say "50 or more". Fixing that one comparison would leave three copies waiting for the next change of the threshold. The rule goes in one place, `HasFreeShipping`, with the threshold and the fee as constants; the banner and the invoice ask it, and the checkout total is the subtotal plus `ShippingCost`, so the three cannot disagree again.

```delphi
unit CartTotals;

interface

// What the cart page shows under the subtotal
function CartBanner(const ASubtotal: Currency): string;
// The shipping line of the invoice
function ShippingCost(const ASubtotal: Currency): Currency;
// What the checkout charges
function CheckoutTotal(const ASubtotal: Currency): Currency;

implementation

uses
  System.SysUtils;

const
  FreeShippingFrom = 50;
  ShippingFee = 4.95;

// The one place of the rule: from FreeShippingFrom on, shipping is free
function HasFreeShipping(const ASubtotal: Currency): Boolean;
begin
  Result := ASubtotal >= FreeShippingFrom;
end;

function CartBanner(const ASubtotal: Currency): string;
begin
  if HasFreeShipping(ASubtotal) then
    Result := 'Free shipping!'
  else
    Result := Format('Add %.2f more for free shipping', [FreeShippingFrom - ASubtotal], TFormatSettings.Invariant);
end;

function ShippingCost(const ASubtotal: Currency): Currency;
begin
  if HasFreeShipping(ASubtotal) then
    Result := 0
  else
    Result := ShippingFee;
end;

function CheckoutTotal(const ASubtotal: Currency): Currency;
begin
  Result := ASubtotal + ShippingCost(ASubtotal);
end;

end.
```

Boxes scanned at the warehouse are refused: `TryParseLotCode` does not read the code printed on their labels, like `L3-07.03.2026`. Fix this Delphi unit.

```delphi
unit LotCodes;

interface

// The code of a production lot: its line and the day it was made, 'L3-20260307'
function LotCode(const ALine: Integer; const ADay: TDateTime): string;
// The code the label printer puts on each box of a lot
function LabelLotCode(const ALine: Integer; const ADay: TDateTime): string;
// Reads a lot code back: its line and its day
function TryParseLotCode(const ACode: string; out ALine: Integer; out ADay: TDateTime): Boolean;

implementation

uses
  System.SysUtils;

function LotCode(const ALine: Integer; const ADay: TDateTime): string;
begin
  Result := Format('L%d-%s', [ALine, FormatDateTime('yyyymmdd', ADay)]);
end;

function LabelLotCode(const ALine: Integer; const ADay: TDateTime): string;
begin
  Result := 'L' + IntToStr(ALine) + '-' + FormatDateTime('dd.mm.yyyy', ADay);
end;

function TryParseLotCode(const ACode: string; out ALine: Integer; out ADay: TDateTime): Boolean;
var
  Dash, Y, M, D: Integer;
  Day: string;
begin
  Result := False;
  ALine := 0;
  ADay := 0;
  Dash := Pos('-', ACode);
  if (Copy(ACode, 1, 1) <> 'L') or (Dash < 3) or not TryStrToInt(Copy(ACode, 2, Dash - 2), ALine) then
    Exit;
  Day := Copy(ACode, Dash + 1, MaxInt);
  if (Length(Day) <> 8) or not TryStrToInt(Copy(Day, 1, 4), Y) or not TryStrToInt(Copy(Day, 5, 2), M) or
    not TryStrToInt(Copy(Day, 7, 2), D) then
    Exit;
  Result := TryEncodeDate(Y, M, D, ADay);
end;

end.
```

`TryParseLotCode` is right; the bug is a second writer. `LotCode` writes `L3-20260307`, and `LabelLotCode` writes the same lot as `L3-07.03.2026`. Teaching the reader a second shape would make every reader of the code carry both, and the next writer would invent a third. So `LabelLotCode` calls `LotCode`: one writer, and the reader stays its strict inverse. Labels already printed in the other shape can be converted once where they are scanned in, instead of loosening the everyday reader.

```delphi
unit LotCodes;

interface

// The code of a production lot: its line and the day it was made, 'L3-20260307'
function LotCode(const ALine: Integer; const ADay: TDateTime): string;
// The code the label printer puts on each box of a lot
function LabelLotCode(const ALine: Integer; const ADay: TDateTime): string;
// Reads a lot code back: its line and its day
function TryParseLotCode(const ACode: string; out ALine: Integer; out ADay: TDateTime): Boolean;

implementation

uses
  System.SysUtils;

function LotCode(const ALine: Integer; const ADay: TDateTime): string;
begin
  Result := Format('L%d-%s', [ALine, FormatDateTime('yyyymmdd', ADay)]);
end;

function LabelLotCode(const ALine: Integer; const ADay: TDateTime): string;
begin
  // the label prints THE lot code: one writer, and TryParseLotCode stays its strict inverse
  Result := LotCode(ALine, ADay);
end;

function TryParseLotCode(const ACode: string; out ALine: Integer; out ADay: TDateTime): Boolean;
var
  Dash, Y, M, D: Integer;
  Day: string;
begin
  Result := False;
  ALine := 0;
  ADay := 0;
  Dash := Pos('-', ACode);
  if (Copy(ACode, 1, 1) <> 'L') or (Dash < 3) or not TryStrToInt(Copy(ACode, 2, Dash - 2), ALine) then
    Exit;
  Day := Copy(ACode, Dash + 1, MaxInt);
  if (Length(Day) <> 8) or not TryStrToInt(Copy(Day, 1, 4), Y) or not TryStrToInt(Copy(Day, 5, 2), M) or
    not TryStrToInt(Copy(Day, 7, 2), D) then
    Exit;
  Result := TryEncodeDate(Y, M, D, ADay);
end;

end.
```

A Delphi record declares its operators as `class operator`: `Add` for `+`, `Multiply` for `*` (here a vector and a `Double`, in that order) and `Equal` for `=`. They live inside the record, so the operators work wherever the type is used. `Vec2` is a global function, declared in the interface outside the record.

```delphi
unit Vectors;

interface

type
  TVec2 = record
    X, Y: Double;
    class operator Add(const A, B: TVec2): TVec2;
    class operator Multiply(const A: TVec2; const K: Double): TVec2;
    class operator Equal(const A, B: TVec2): Boolean;
    function Length: Double;
  end;

function Vec2(const AX, AY: Double): TVec2;

implementation

function Vec2(const AX, AY: Double): TVec2;
begin
  Result.X := AX;
  Result.Y := AY;
end;

class operator TVec2.Add(const A, B: TVec2): TVec2;
begin
  Result := Vec2(A.X + B.X, A.Y + B.Y);
end;

class operator TVec2.Multiply(const A: TVec2; const K: Double): TVec2;
begin
  Result := Vec2(A.X * K, A.Y * K);
end;

class operator TVec2.Equal(const A, B: TVec2): Boolean;
begin
  Result := (A.X = B.X) and (A.Y = B.Y);
end;

function TVec2.Length: Double;
begin
  Result := Sqrt(X * X + Y * Y);
end;

end.
```

Thumbnails rendered by the gallery are never cleaned up: `parse_thumb_key` returns None for their keys, like `thumb/1234/320px`. Fix this Python module.

```python
"""Keys of the thumbnail cache."""


def thumb_key(photo_id, width):
    """The cache key of a photo's thumbnail of one width."""
    return f"thumb/{photo_id}/w{width}"


def gallery_thumb_key(photo_id, width):
    """The key the gallery stores when it renders a thumbnail."""
    return "thumb/" + str(photo_id) + "/" + str(width) + "px"


def parse_thumb_key(key):
    """(photo_id, width) of a thumbnail key, or None when it is not one."""
    parts = key.split("/")
    if len(parts) != 3 or parts[0] != "thumb" or not parts[1].isdigit():
        return None
    if not parts[2].startswith("w") or not parts[2][1:].isdigit():
        return None
    return int(parts[1]), int(parts[2][1:])
```

`parse_thumb_key` is right; the bug is a second writer. `thumb_key` writes `thumb/1234/w320`, and `gallery_thumb_key` writes the same key as `thumb/1234/320px`. Teaching the reader a second shape would make every reader of the key carry both, and the next writer would invent a third. So `gallery_thumb_key` calls `thumb_key`: one writer, and the reader stays its strict inverse. Keys already stored in the other shape can be converted once, instead of loosening the everyday reader.

```python
"""Keys of the thumbnail cache."""


def thumb_key(photo_id, width):
    """The cache key of a photo's thumbnail of one width."""
    return f"thumb/{photo_id}/w{width}"


def gallery_thumb_key(photo_id, width):
    """The key the gallery stores when it renders a thumbnail: THE thumbnail key, from its one writer."""
    return thumb_key(photo_id, width)


def parse_thumb_key(key):
    """(photo_id, width) of a thumbnail key, or None when it is not one."""
    parts = key.split("/")
    if len(parts) != 3 or parts[0] != "thumb" or not parts[1].isdigit():
        return None
    if not parts[2].startswith("w") or not parts[2][1:].isdigit():
        return None
    return int(parts[1]), int(parts[2][1:])
```
